use serde_json::{json,Value};
use std::{path::{Path,PathBuf},process::{Command,Stdio},io::Read,sync::Mutex,time::{Duration,Instant,SystemTime,UNIX_EPOCH}};
use tauri::Manager;
use crate::repository::{data_dir,db_path};
#[cfg(windows)]use std::os::windows::process::CommandExt;
static ACTIVE:Mutex<bool>=Mutex::new(false);
fn hidden(c:&mut Command){#[cfg(windows)]{c.creation_flags(0x08000000);}}
struct Runtime{node:PathBuf,worker:PathBuf}
fn node_path(path:PathBuf)->PathBuf{#[cfg(windows)]{let text=path.to_string_lossy();if let Some(rest)=text.strip_prefix(r"\\?\UNC\"){return PathBuf::from(format!(r"\\{}",rest));}if let Some(rest)=text.strip_prefix(r"\\?\"){return PathBuf::from(rest);}}path}
fn runtime_at(root:&Path)->Option<Runtime>{let r=Runtime{node:root.join("runtime/node.exe"),worker:root.join("worker")};(r.node.is_file()&&r.worker.join("runner.mjs").is_file()).then_some(r)}
fn runtime(app:&tauri::AppHandle)->Result<Runtime,String>{let base=app.path().resource_dir().map_err(|_|"インストール先を確認できません")?;let mut result=runtime_at(&base);
 if result.is_none(){if let Ok(exe)=std::env::current_exe(){if let Some(folder)=exe.parent(){if matches!(folder.file_name().and_then(|v|v.to_str()),Some("release"|"debug"))&&folder.parent().and_then(|p|p.file_name()).and_then(|v|v.to_str())==Some("target"){if let Some(project)=folder.ancestors().nth(3){let node=project.join("src-tauri/runtime/node.exe");let worker=project.join("worker");if node.is_file()&&worker.join("runner.mjs").is_file(){result=Some(Runtime{node,worker});}}}}}}
 let r=result.ok_or("起動用ファイルが見つかりません。修正版インストーラーで入れ直してください")?;
 for file in ["launcher.cjs","check-runtime.mjs","runner.mjs","browser.mjs","lib.mjs","flow.mjs","restaurant-board.mjs","node_modules/playwright/package.json","node_modules/playwright-core/package.json"]{if !r.worker.join(file).is_file(){return Err(format!("起動用ファイルが不足しています（{}）。修正版インストーラーで入れ直してください",file));}}Ok(Runtime{node:node_path(r.node),worker:node_path(r.worker)})
}
fn read_job(path:&Path)->Value{std::fs::read(path).ok().and_then(|b|serde_json::from_slice(&b).ok()).unwrap_or(json!({"state":"idle"}))}
fn write_job(path:&Path,value:&Value)->Result<(),String>{let temp=path.with_extension(format!("{}-{}.tmp",std::process::id(),now()));std::fs::write(&temp,value.to_string()).map_err(|_|"起動状態を保存できません")?;if std::fs::rename(&temp,path).is_err(){std::fs::write(path,value.to_string()).map_err(|_|"起動状態を更新できません")?;let _=std::fs::remove_file(temp);}Ok(())}
#[cfg(windows)]fn alive(pid:u32)->bool{#[link(name="kernel32")]extern "system"{fn OpenProcess(access:u32,inherit:i32,pid:u32)->*mut std::ffi::c_void;fn GetExitCodeProcess(handle:*mut std::ffi::c_void,code:*mut u32)->i32;fn CloseHandle(handle:*mut std::ffi::c_void)->i32;}if pid==0{return false;}unsafe{let h=OpenProcess(0x1000,0,pid);if h.is_null(){return false;}let mut code=0;let ok=GetExitCodeProcess(h,&mut code)!=0&&code==259;CloseHandle(h);ok}}
#[cfg(not(windows))]fn alive(_pid:u32)->bool{false}
fn lock_alive(dir:&Path)->bool{std::fs::read_to_string(dir.join("sync.lock")).ok().and_then(|s|s.trim().parse().ok()).is_some_and(alive)}
fn now()->u128{SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos()}
fn startup_error(stderr:&str,exit:Option<i32>)->(&'static str,String){if stderr.contains("ERR_MODULE_NOT_FOUND")||stderr.contains("Cannot find module"){("STARTUP_FILES_MISSING","起動に必要なファイルを読み込めません。修正版インストーラーで入れ直してください。".into())}else{("STARTUP_PROCESS_EXITED",format!("起動処理が途中で終了しました（終了コード {}）。「起動環境を確認」の結果を確認してください。",exit.map(|v|format!("0x{:08X}",v as u32)).unwrap_or_else(||"不明".into())))}}
#[tauri::command]
pub fn start_automation(app:tauri::AppHandle,action:String,start:String,end:String)->Result<(),String>{if !["login","sync"].contains(&action.as_str()){return Err("不正な操作です".into());}let r=runtime(&app)?;let dir=data_dir(&app)?;let mut active=ACTIVE.lock().map_err(|_|"起動状態を確認できません")?;if *active||lock_alive(&dir){return Err("取得またはログイン処理が実行中です。終了してから開いてください".into());}
 let job=dir.join("job.json");let request=now().to_string();let initial=json!({"state":"starting","phase":"starting","action":action,"requestId":request,"message":if action=="login"{"ログイン用ブラウザーを起動しています…"}else{"予約取得を開始しています…"},"at":request});write_job(&job,&initial)?;
 // Node cannot resolve a verbatim Windows path as its entry script. Resolve it from the worker directory instead.
 let mut command=Command::new(&r.node);command.current_dir(&r.worker).env_remove("NODE_OPTIONS").env_remove("NODE_PATH").arg("launcher.cjs").arg("--db").arg(db_path(&app)?).arg("--action").arg(&action).arg("--start").arg(start).arg("--end").arg(end).arg("--request").arg(&request).stdin(Stdio::null()).stdout(Stdio::null()).stderr(Stdio::piped());hidden(&mut command);
 let mut child=match command.spawn(){Ok(c)=>c,Err(e)=>{let message=format!("同梱ランタイムを起動できません（Windowsエラー {}）。「起動環境を確認」を実行してください。",e.raw_os_error().map(|v|v.to_string()).unwrap_or_else(||"不明".into()));let _=write_job(&job,&json!({"state":"error","action":action,"requestId":request,"message":message,"code":"RUNTIME_START_FAILED","at":now().to_string()}));return Err(message);}};
 // Keep the child handle: an import or runtime failure must not disappear silently.
 *active=true;let stderr=child.stderr.take();let drain=std::thread::spawn(move||{let mut result=Vec::new();if let Some(mut stream)=stderr{let mut block=[0u8;1024];loop{match stream.read(&mut block){Ok(0)|Err(_)=>break,Ok(n)=>{let keep=n.min(8192usize.saturating_sub(result.len()));result.extend_from_slice(&block[..keep]);}}}}String::from_utf8_lossy(&result).into_owned()});
 std::thread::spawn(move||{let started=Instant::now();let status=loop{match child.try_wait(){Ok(Some(s))=>break Some(s),Err(_)=>break None,Ok(None)=>{let value=read_job(&job);if started.elapsed()>Duration::from_secs(45)&&value["requestId"]==request&&value["state"]=="starting"{let _=child.kill();break child.wait().ok();}std::thread::sleep(Duration::from_millis(200));}}};let stderr=drain.join().unwrap_or_default();let current=read_job(&job);if current["requestId"]==request&&matches!(current["state"].as_str(),Some("starting"|"running")){let(code,message)=startup_error(&stderr,status.and_then(|s|s.code()));let _=write_job(&job,&json!({"state":"error","action":action,"requestId":request,"code":code,"message":message,"at":now().to_string()}));}if let Ok(mut a)=ACTIVE.lock(){*a=false;}});Ok(())
}
#[tauri::command]
pub fn automation_status(app:tauri::AppHandle)->Result<Value,String>{let dir=data_dir(&app)?;let path=dir.join("job.json");let mut value=read_job(&path);let active=ACTIVE.lock().map(|v|*v).unwrap_or(true);if matches!(value["state"].as_str(),Some("running"|"starting"))&&!active&&!lock_alive(&dir){value=json!({"state":"error","message":"前回の起動処理は終了しています。もう一度「ログイン画面を開く」を押してください。","code":"PREVIOUS_PROCESS_ENDED","at":now().to_string()});let _=write_job(&path,&value);}Ok(value)}
#[tauri::command]
pub fn finish_login(app:tauri::AppHandle)->Result<(),String>{let dir=data_dir(&app)?;let job=read_job(&dir.join("job.json"));if job["state"]!="running"||job["action"]!="login"||job["phase"]!="login"{return Err("ログイン用ブラウザーを開いてから操作してください".into());}std::fs::write(dir.join("login-confirm"),b"confirmed").map_err(|_|"ログイン確認を通知できません".into())}
#[tauri::command]
pub async fn automation_diagnostics(app:tauri::AppHandle,channel:String)->Result<Value,String>{let r=runtime(&app)?;let dir=data_dir(&app)?;tauri::async_runtime::spawn_blocking(move||{let mut c=Command::new(&r.node);c.current_dir(&r.worker).env_remove("NODE_OPTIONS").env_remove("NODE_PATH").arg("check-runtime.mjs").arg(if channel=="chrome"{"chrome"}else{"msedge"}).arg("--data-dir").arg(dir).stdin(Stdio::null()).stdout(Stdio::piped()).stderr(Stdio::piped());hidden(&mut c);let mut child=c.spawn().map_err(|e|format!("同梱ランタイムを起動できません（Windowsエラー {:?}）。修正版で入れ直してください。",e.raw_os_error()))?;let deadline=Instant::now()+Duration::from_secs(35);loop{if child.try_wait().map_err(|_|"起動状態を確認できません")?.is_some(){break;}if Instant::now()>deadline{let _=child.kill();let _=child.wait();return Err("起動環境の確認が時間切れになりました。ブラウザー単体で起動できるか確認してください。".into());}std::thread::sleep(Duration::from_millis(100));}let output=child.wait_with_output().map_err(|_|"確認結果を読み込めません")?;serde_json::from_slice::<Value>(&output.stdout).map_err(|_|startup_error(&String::from_utf8_lossy(&output.stderr),output.status.code()).1)}).await.map_err(|_|"起動環境の確認に失敗しました")?}
#[cfg(test)]mod tests{use super::*;#[test]fn missing_import_is_reported_without_private_stderr(){let(c,m)=startup_error("ERR_MODULE_NOT_FOUND secret customer",Some(1));assert_eq!(c,"STARTUP_FILES_MISSING");assert!(!m.contains("secret"));let(_,m)=startup_error("private",Some(-1073741515));assert!(m.contains("0xC0000135"));assert!(!m.contains("private"));}#[test]fn installed_runtime_is_selected_only_with_both_parts(){let p=std::env::temp_dir().join(format!("runtime-path-test-{}",now()));std::fs::create_dir_all(p.join("runtime")).unwrap();std::fs::create_dir_all(p.join("worker")).unwrap();std::fs::write(p.join("runtime/node.exe"),b"test").unwrap();assert!(runtime_at(&p).is_none());std::fs::write(p.join("worker/runner.mjs"),b"test").unwrap();assert!(runtime_at(&p).is_some());std::fs::remove_dir_all(p).unwrap();}}
